mapper.select:
SELECT * FROM ( SELECT r.id AS room_id, r.building_id AS building_id, b.name AS building_name, b.code AS building_code, r.region_id AS region_id, rg.name AS region_name, b.city AS city, b.address AS address, r.room_no AS room_no, r.floor_no AS floor_no, r.room_type AS room_type, r.capacity AS capacity, r.gender_limit AS gender_limit, r.status AS status, r.price_per_night AS price_per_night, r.currency AS currency, r.facilities AS facilities, r.remark AS remark, (SELECT COUNT(*) FROM dorm_bed bd WHERE bd.room_id = r.id AND bd.status = 'IDLE') AS idle_beds,
(SELECT COUNT(*) FROM dorm_bed bd WHERE bd.room_id = r.id AND bd.status = 'IDLE') AS available_beds,
(SELECT COUNT(*) FROM dorm_bed bd2 WHERE bd2.room_id = r.id AND bd2.status <> 'DISABLED'
AND NOT EXISTS ( SELECT 1 FROM stay_apply a WHERE a.bed_id = bd2.id AND a.status IN ('APPROVED', 'CHECKED_IN') AND a.check_in_date < #{checkOut} AND #{checkIn} < a.check_out_date )
) AS bookable_beds, (SELECT COUNT(*) FROM dorm_bed bd3 WHERE bd3.room_id = r.id AND bd3.status <> 'DISABLED') AS total_beds FROM dorm_room r JOIN dorm_building b ON b.id = r.building_id JOIN region rg ON rg.id = r.region_id WHERE r.status = 'OPEN' AND b.status = 1 AND rg.status = 1
AND r.region_id = #{regionId}
AND r.building_id = #{buildingId}
AND (b.city LIKE CONCAT('%', #{city}, '%') OR b.name LIKE CONCAT('%', #{city}, '%'))
AND r.room_type = #{roomType}
AND (r.gender_limit = 'ANY' OR r.gender_limit = #{gender})
) t WHERE t.available_beds >= #{minBeds} ORDER BY t.region_id, t.building_code, t.floor_no, t.room_no
